#!/bin/sh
# Generated by FWShift: a Google Cloud network firewall policy, created with gcloud. Read the report first: what is
# not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE                              prints the commands; needs no access to Google Cloud
#   GCLOUD_OPTS='--project my-project' sh THIS_FILE     creates the policy and its rules
#
# The policy is associated with no network: nothing changes for any traffic until you associate it:
#   gcloud compute network-firewall-policies associations create --firewall-policy fwshift --network NETWORK --global-firewall-policy
# It decides every connection of that network. Set the network's enforcement order to BEFORE_CLASSIC_FIREWALL, or
# the VPC firewall rules of the network decide first. A policy of the same name stops the script before anything is
# created; a command gcloud refuses stops it where it is (delete the policy and run it again).
set -u
DRY_RUN="${DRY_RUN:-}"
GCLOUD_OPTS="${GCLOUD_OPTS:-}"
POLICY=fwshift
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
run() {
  if [ -n "$DRY_RUN" ]; then printf 'gcloud' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gcloud "$@" $GCLOUD_OPTS --quiet >/dev/null || fail "gcloud $1 $2 $3 $4"
}
if [ -z "$DRY_RUN" ] && gcloud compute network-firewall-policies describe "$POLICY" --global $GCLOUD_OPTS >/dev/null 2>&1; then
  fail "a network firewall policy named $POLICY exists already; nothing was created"
fi

run compute network-firewall-policies create "$POLICY" --global '--description=Generated by FWShift; review the conversion report before associating it'

run compute network-firewall-policies rules create 1000 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging --description=lab-to-inside
run compute network-firewall-policies rules create 1010 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging --description=lab-to-inside
run compute network-firewall-policies rules create 1020 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1030 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1040 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1050 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny

# Not written:
#   inside-ping: the source of the rule is in zone trust, and a rule of Google Cloud names no zone: give the networks behind trust with --zone-network; the destination of the rule is in zone trust, and a rule of Google Cloud names no zone: give the networks behind trust with --zone-network
#   inside-to-web: the source of the rule is in zone trust, and a rule of Google Cloud names no zone: give the networks behind trust with --zone-network; the destination of the rule is in zone untrust, and a rule of Google Cloud names no zone: give the networks behind untrust with --zone-network
#   publish-web: the source of the rule is in zone untrust, and a rule of Google Cloud names no zone: give the networks behind untrust with --zone-network; the destination of the rule is in zone dmz, and a rule of Google Cloud names no zone: give the networks behind dmz with --zone-network
#   block-country: references 'blocked-country': address entry blocked-country: country XX, which the configuration does not resolve to addresses; the destination 'blocked-country' holds members only its platform knows; a rule of Google Cloud names addresses
#   inside-to-servers: the source of the rule is in zone trust, and a rule of Google Cloud names no zone: give the networks behind trust with --zone-network; the destination of the rule is in zone dmz, and a rule of Google Cloud names no zone: give the networks behind dmz with --zone-network
#   lab-updates: the source of the rule is in zone lab, and a rule of Google Cloud names no zone: give the networks behind lab with --zone-network; host name object update-site: the rules are written with addresses
#   app-clients: schedule 'office-hours' is not converted; the rule would apply at all times; the source of the rule is in zone trust, and a rule of Google Cloud names no zone: give the networks behind trust with --zone-network; host name object files.example.org: the rules are written with addresses
#   p2p: not converted: application BitTorrent: application identification narrows the match; the source of the rule is in zone trust, and a rule of Google Cloud names no zone: give the networks behind trust with --zone-network; the destination of the rule is in zone untrust, and a rule of Google Cloud names
#   v6-out: the source of the rule is in zone trust, and a rule of Google Cloud names no zone: give the networks behind trust with --zone-network; the destination of the rule is in zone untrust, and a rule of Google Cloud names no zone: give the networks behind untrust with --zone-network
#   tunnels-to-partners: the source of the rule is in zone lab, dmz, and a rule of Google Cloud names no zone: give the networks behind lab, dmz with --zone-network; the destination 'partners' holds members only its platform knows; a rule of Google Cloud names addresses
#   to-branch-vpn: not converted: action tunnel vpn-to-branch: traffic of a VPN tunnel only; the source of the rule is in zone trust, and a rule of Google Cloud names no zone: give the networks behind trust with --zone-network; the destination of the rule is in zone untrust, and a rule of Google Cloud names no zone: g
#   contractors-out: references 'wild-hosts': address entry wild-hosts: wildcard address '10.10.0.5 0.0.255.0'; source user match role contractors is not converted; the source 'wild-hosts' holds members only its platform knows; a rule of Google Cloud names addresses; the destination of the rule is in zone untrust, and a
#   rule 13: the source of the rule is in zone trust, and a rule of Google Cloud names no zone: give the networks behind trust with --zone-network; the destination of the rule is in zone lab, and a rule of Google Cloud names no zone: give the networks behind lab with --zone-network

echo 'Done. Associate the policy with the network when you are ready; until then nothing changes.' >&2
